CREATE TABLE ticket_attachments (id BIGINT AUTO_INCREMENT, ticket_id BIGINT NOT NULL, filename VARCHAR(255) NOT NULL, content_type VARCHAR(120) NOT NULL, size_bytes BIGINT NOT NULL, uploaded_by_id BIGINT NOT NULL, uploaded_at TIMESTAMP NOT NULL, content LONGBLOB NOT NULL, CONSTRAINT pk_ticket_attachments PRIMARY KEY (id), CONSTRAINT fk_attachment_ticket FOREIGN KEY (ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, CONSTRAINT fk_attachment_uploader FOREIGN KEY (uploaded_by_id) REFERENCES users(id));
CREATE TABLE ticket_notifications (id BIGINT AUTO_INCREMENT, ticket_id BIGINT NOT NULL, recipient_id BIGINT NOT NULL, title VARCHAR(200) NOT NULL, message VARCHAR(1000) NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL, CONSTRAINT pk_ticket_notifications PRIMARY KEY (id), CONSTRAINT fk_notification_ticket FOREIGN KEY (ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, CONSTRAINT fk_notification_recipient FOREIGN KEY (recipient_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX idx_attachment_ticket ON ticket_attachments(ticket_id);
CREATE INDEX idx_notification_recipient ON ticket_notifications(recipient_id, is_read);
